import {SOLO_NAMES,SOLO_HEROES,SOLO_SKILLS,skillById,experience,itemInfo,ITEMS,upgradeCosts,lootPreview,QUALITY,equipmentClass} from './campaign-growth-data.mjs';
import {heroStats,learnSkill,equipSkill,upgradeSkill,equipItem,sellItem,useItem,chooseHero,transferPower,summonSolo,forgeItem,levelEquipment,combineStones} from './campaign-profile.mjs';
import {splashStyle} from './lobby-art.mjs?v=20261030-duel12';
import {skillArtStyle} from './skill-icons.mjs?v=20261030-duel12';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const titles={character:'角色',bag:'背包',skills:'技能',artifact:'法器',pet:'灵宠',forge:'锻造炉',summon:'英雄召唤'};
const indexes={character:0,bag:1,skills:2,artifact:3,pet:4,forge:5};
export function sheetStyle(sheet,index,meta=null){const fallback={ui:[3,2,'ui-icons-v1.png'],items:[4,4,'items-v1.png'],equipment:[4,3,'equipment-v1.png'],armors:[4,3,'armors-v1.png']},m=meta?.[sheet];if(m?.frames?.[index]){const r=m.frames[index].rect;return `background-image:url('assets/campaign-growth/${m.file}');background-size:${m.size[0]/r[2]*100}% ${m.size[1]/r[3]*100}%;background-position:${r[0]/Math.max(1,m.size[0]-r[2])*100}% ${r[1]/Math.max(1,m.size[1]-r[3])*100}%`;}
 const [cols,rows,file]=fallback[sheet]||fallback.items;return `background-image:url('assets/campaign-growth/${file}');background-size:${cols*100}% ${rows*100}%;background-position:${cols>1?index%cols/(cols-1)*100:0}% ${rows>1?Math.floor(index/cols)/(rows-1)*100:0}%`;}
export function soloSkillStyle(hero,skill){return skill?.column?`background-image:url('assets/campaign-growth/hero-${hero}-icons-v1.png');background-size:300% 100%;background-position:${skill.row*50}% 0%`:skillArtStyle(hero,skill?.key||'q');}
export function itemTip(item){const i=itemInfo(item);if(!i)return '';let copy=i.description;if(item.type==='equipment'){copy+=` 适用：${item.role==='melee'?'雷行者、影刃':'焰术师、森灵、霜语者、星术师'}。`;copy+=item.slot==='weapon'?`攻击加成${Math.round(QUALITY[item.quality||0].power*100)}%起，提供暴击/高品质吸血；无防御属性。`:'提升生命、防御和少量自然回血；无攻击属性。';}return `${i.name}\n${copy}${i.sell?`\n出售：${i.sell}金币／件`:''}`;}
export function itemToken(item,{meta=null,label=false,extra='',action=''}={}){const i=itemInfo(item);if(!i)return '';return `<button type="button" class="loot-token has-tip" aria-label="${esc(i.name)}${item.count>1?' × '+item.count:''}" style="--rarity:${i.color||'#bcab78'}" data-tip="${esc(itemTip(item))}" ${action}><span class="item-art" style="${sheetStyle(i.sheet||'items',i.icon,meta)}"></span>${item.count>1?`<b class="item-count">${item.count}</b>`:''}${label?`<small>${esc(i.name)}</small>`:''}${extra}</button>`;}
export function renderLootPreview(el,id,meta){const p=lootPreview(id),items=[...p.guaranteed,{type:'ticket',count:1}];if(id===1)items.push({type:'heroChoice',count:1});else for(const role of ['melee','staff'])for(const slot of ['weapon','armor'])items.push({type:'equipment',role,slot,stage:id,quality:id>=10?5:id>=8?4:id>=5?3:id===4?1:0,count:1});el.innerHTML=`<h3>秘境战利品 <small>悬停查看用途 · 首领掉落需 C 拾取</small></h3><div class="loot-preview-row">${items.map(i=>itemToken(i,{meta,label:true})).join('')}</div><p>${p.equipment} · 首通抽奖券必掉，重刷50%；第一关自选宝箱仅首次。</p>`;}
export class CampaignSystemUI{
 constructor({getProfile,getWorld,onPause,onClose,onChange,meta=null}){Object.assign(this,{getProfile,getWorld,onPause,onClose,onChange,meta});this.panel='character';this.hero=null;this.selectedItem=null;this.message='';this.dialog=document.createElement('dialog');this.dialog.id='solo-system';document.body.append(this.dialog);this.dialog.addEventListener('cancel',e=>{e.preventDefault();this.close();});this.dialog.addEventListener('click',e=>this.action(e));this.dialog.addEventListener('change',e=>{if(e.target.matches('[data-hero-view]')){this.hero=e.target.value;this.message='';this.render();}});this.dialog.addEventListener('dragstart',e=>{const card=e.target.closest('[data-drag-skill]');if(card)e.dataTransfer.setData('text/plain',card.dataset.dragSkill);});this.dialog.addEventListener('dragover',e=>{if(e.target.closest('[data-skill-slot]'))e.preventDefault();});this.dialog.addEventListener('drop',e=>{const slot=e.target.closest('[data-skill-slot]');if(!slot)return;e.preventDefault();const id=e.dataTransfer.getData('text/plain'),s=skillById(id);this.mutate(()=>{if(s?.key!==slot.dataset.skillSlot)throw Error('同一行只能放入对应F/E/R槽');equipSkill(this.getProfile(),this.hero,id);});});this.tooltip=document.createElement('div');this.tooltip.className='solo-tooltip';this.tooltip.role='tooltip';this.tooltip.hidden=true;document.body.append(this.tooltip);const tip=e=>{const el=e.target.closest('.has-tip');if(!el){this.tooltip.hidden=true;return;}const r=el.getBoundingClientRect();const layer=el.closest('dialog[open]')||document.body;if(this.tooltip.parentNode!==layer)layer.append(this.tooltip);this.tooltip.textContent=el.dataset.tip;this.tooltip.hidden=false;this.tooltip.style.left=Math.max(10,Math.min(innerWidth-300,r.left))+'px';this.tooltip.style.top=Math.max(10,Math.min(innerHeight-150,r.bottom+8))+'px';};document.addEventListener('pointerover',tip);document.addEventListener('focusin',tip);document.addEventListener('pointerout',e=>{if(e.target.closest('.has-tip'))this.tooltip.hidden=true;});}
 open(panel='character'){this.onPause();this.panel=panel;this.hero=this.getWorld()?.hero||this.getProfile().selected;this.message='';this.render();if(!this.dialog.open)this.dialog.showModal();}
 close(){this.dialog.close();this.tooltip.hidden=true;this.onClose();}
 mutate(fn){try{const result=fn();this.message=typeof result==='string'?result:'已保存';this.onChange();}catch(e){this.message=e.message;}this.render();}
 render(){const p=this.getProfile(),w=this.getWorld(),h=this.hero||p.selected;this.hero=h;this.dialog.dataset.panel=this.panel;this.dialog.innerHTML=`<header class="system-heading"><div><small>THE TRAVELLER’S ARCHIVE</small><h2>${titles[this.panel]}</h2></div><div class="solo-wallet"><span>金币 <b>${p.coins}</b></span><span>抽奖券 <b>${p.tickets}</b></span></div><button class="system-close" data-close aria-label="关闭面板，继续游戏">×</button></header><nav class="system-tabs">${Object.keys(indexes).map(k=>`<button data-panel="${k}" aria-current="${this.panel===k?'page':'false'}"><i class="nav-icon" style="${sheetStyle('ui',indexes[k],this.meta)}"></i>${titles[k]}</button>`).join('')}</nav><div class="system-body">${this.content(p,w,h)}</div><footer class="system-footer"><span role="status">${esc(this.message)||'档案已在本机保存 · 面板打开时战斗暂停'}</span><button data-close>返回${w?'战斗':'世界地图'} ›</button></footer>`;}
 selector(p,h){return `<label class="hero-view-label">查看英雄 <select data-hero-view>${p.owned.map(id=>`<option value="${id}" ${id===h?'selected':''}>${SOLO_NAMES[id]}</option>`).join('')}</select></label>`;}
 content(p,w,h){if(this.panel==='character')return this.character(p,w,h);if(this.panel==='bag')return this.bag(p,w,h);if(this.panel==='skills')return this.skills(p,h);if(this.panel==='forge')return this.forge(p);if(this.panel==='summon')return this.summon(p);const unlock=this.panel==='artifact'?4:5;return `<div class="future-system"><i style="${sheetStyle('ui',indexes[this.panel],this.meta)}"></i><small>COMING CHAPTER</small><h3>${titles[this.panel]}</h3><p>${p.cleared.includes(unlock)?'此入口已解锁，等待后续加入专属玩法。':`通关第${unlock}关后解锁`}</p><span>本轮只开放入口与状态，内部功能将在后续设计。</span></div>`;}
 character(p,w,h){const record=p.heroes[h],s=heroStats(p,h),xp=experience(record.exp),active=w?.hero===h,slots=['weapon','armor','artifact'];return `<div class="character-layout"><section class="character-portrait"><div class="character-level"><b>Lv.${xp.level}</b> ${SOLO_NAMES[h]}<small>${xp.xp} / ${xp.next} 经验</small><progress max="${xp.next}" value="${xp.xp}"></progress></div><div class="solo-hero-art" style="${splashStyle(h)}"></div>${this.selector(p,h)}<button data-select-hero ${w?'disabled':''}>设为出战英雄</button></section><section class="character-stats"><h3>旅者属性 <small>等级与装备共同生效</small></h3><dl>${[['生命',`${Math.ceil(active?w.player.hp:s.maxHp)} / ${s.maxHp}`],['法力',`${Math.floor(active?w.player.mp:s.maxMp)} / ${s.maxMp}`],['攻击力',s.attack],['暴击率',(s.crit*100).toFixed(1)+'%'],['吸血',(s.lifesteal*100).toFixed(1)+'%'],['自然回血',s.regen.toFixed(2)+' / 秒'],['攻击速度',s.attackSpeed.toFixed(2)+'×'],['防御减伤',(s.armor*100).toFixed(1)+'%']].map(([k,v])=>`<dt>${k}</dt><dd>${v}</dd>`).join('')}</dl><p class="system-note">每级：基础生命+3% · 法力+2.5% · 攻击+2%<br>武器只影响输出，盔甲只影响生存；法器与灵宠尚未提供属性。</p><div class="equipment-slots">${slots.map((slot,i)=>{const item=p.bag.find(v=>v.id===record.equipment[slot]);return `<div><small>${['武器','盔甲','法器'][i]}</small>${item?itemToken(item,{meta:this.meta,action:`data-item="${item.id}"`}):`<span class="empty-equipment" style="${sheetStyle(i===0?'equipment':i===1?'armors':'ui',i<2?(equipmentClass(h)==='melee'?0:6):3,this.meta)}"></span>`}${item?`<button data-unequip="${slot}">卸下</button>`:'<p>尚未装备</p>'}</div>`;}).join('')}</div><div class="power-transfer"><h4>传输功力</h4><p>目标低于5级，每人只接收一次；传出者回到1级，装备和技能保留。接收的经验不可转传。</p><select id="transfer-target">${p.owned.filter(id=>id!==h).map(id=>`<option value="${id}">${SOLO_NAMES[id]} Lv.${experience(p.heroes[id].exp).level}</option>`).join('')}</select><button data-transfer ${p.owned.length<2?'disabled':''}>传输功力</button></div><button class="subtle-button" data-panel="summon">英雄召唤 · 使用抽奖券 ›</button></section></div>`;}
 bag(p,w,h){const item=p.bag.find(i=>i.id===this.selectedItem)||p.bag[0],info=item&&itemInfo(item);return `<div class="bag-layout"><section><div class="section-title"><h3>行囊</h3><small>${p.bag.length} 种物品 · 相同补给堆叠</small></div><div class="bag-grid">${p.bag.map(i=>itemToken(i,{meta:this.meta,extra:i.id===item?.id?'<em class="selected-ring"></em>':'',action:`data-item="${i.id}"`})).join('')}${Array.from({length:Math.max(0,30-p.bag.length)},()=>'<div class="empty-bag-slot"></div>').join('')}</div><p class="system-note">首领战后靠近掉落按 C 拾取；靠近传送门按 X 结算。</p></section><aside class="item-detail">${item?`${itemToken(item,{meta:this.meta})}<h3 style="color:${info.color||'#efddae'}">${info.name}</h3><p>${esc(itemTip(item)).replaceAll('\n','<br>')}</p><small>持有数量 ${item.count}</small><div class="item-actions">${info.kind==='equipment'?`<button data-equip="${item.id}">装备给${SOLO_NAMES[h]}</button>`:info.kind==='heroChoice'?`<label>选择未拥有英雄<select id="choice-hero">${SOLO_HEROES.filter(id=>!p.owned.includes(id)).map(id=>`<option value="${id}">${SOLO_NAMES[id]}</option>`).join('')}</select></label><button data-choice="${item.id}">打开自选宝箱</button>`:['coins','xp','health','mana'].includes(info.kind)?`<button data-use="${item.id}">使用一件</button>`:''}${info.sell?`<button class="subtle-button" data-sell="${item.id}">出售一件 · ${info.sell}金币</button>`:''}</div>`:'<h3>行囊空空</h3><p>探索秘境，收集新的战利品。</p>'}</aside></div>`;}
 skills(p,h){const record=p.heroes[h];return `${this.selector(p,h)}<div class="skills-grid">${[0,1,2].flatMap(row=>[0,1].map(col=>{const s=SOLO_SKILLS[h].find(s=>s.row===row&&s.column===col),rank=record.skills[s.id],known=rank!==undefined,equipped=record.slots[s.key]===s.id;return `<article class="skill-card ${known?'':'locked'} ${equipped?'equipped':''}" draggable="${known}" data-drag-skill="${s.id}"><i class="system-skill-art" style="${soloSkillStyle(h,s)}"></i><div><small>${['F · 技艺','E · 秘术','R · 终式'][row]} · ${col?'新分支':'原生招式'}</small><h3>${s.name} ${known?`<span>+${rank}/5</span>`:''}</h3><p>${s.description}</p><small>消耗${s.mana}法力 · 强化：效果+8% / 冷却−2%</small><div class="skill-actions">${known?`<button data-equip-skill="${s.id}" ${equipped?'disabled':''}>${equipped?'已佩戴':'佩戴到'+s.key.replace('q','F').toUpperCase()}</button><button data-upgrade-skill="${s.id}" ${rank>=5?'disabled':''}>${rank>=5?'已满强化':`强化 · ${upgradeCosts[row][rank]}金币`}</button>`:`<button data-learn="${s.id}">学习 · ${s.cost}金币</button>`}</div></div></article>`;})).join('')}</div><div class="skill-loadout">${['q','e','r'].map((key,i)=>{const s=skillById(record.slots[key]);return `<div data-skill-slot="${key}"><kbd>${['F','E','R'][i]}</kbd>${s?`<i style="${soloSkillStyle(h,s)}"></i><strong>${s.name}</strong>`:'<span>尚未学习</span>'}<small>第${i+1}行二选一 · 拖动或点击佩戴</small></div>`;}).join('')}</div>`;}
 forge(p){const equipment=p.bag.filter(i=>i.type==='equipment');return `<div class="forge-layout"><section class="forge-illustration"><i style="${sheetStyle('ui',5,this.meta)}"></i><h3>符文锻造炉</h3><p>金币强化提升细微属性，灵石升品带来阶段提升。装备的颜色品质保留。</p><div class="stone-combine">${['stoneSmall','stoneMedium'].map(type=>`<button data-combine="${type}">${ITEMS[type].name} ×3 → ${type==='stoneSmall'?'中等':'高阶'}灵石</button>`).join('')}</div></section><section><h3>可锻造装备</h3>${equipment.length?equipment.map(i=>`<article class="forge-equipment">${itemToken(i,{meta:this.meta})}<div><strong>${itemInfo(i).name}</strong><p>${QUALITY[i.quality||0].name} · ${i.rank||0}品 · 强化${i.level||0}级</p><button data-level-equipment="${i.id}">金币强化 · ${60+(i.level||0)*45+(i.quality||0)*30}</button><button data-forge="${i.id}" ${(i.rank||0)>=3?'disabled':''}>${(i.rank||0)>=3?'三品已满':`升${(i.rank||0)+1}品 · ${[10,10,30][i.rank||0]}${['小','中等','高阶'][i.rank||0]}灵石`}</button></div></article>`).join(''):'<div class="empty-forge"><p>尚未获得装备</p><small>从第2关起，首领掉落武器与盔甲。</small></div>'}</section></div>`;}
 summon(p){const targets=SOLO_HEROES.filter(id=>!p.owned.includes(id));return `<div class="summon-archive"><small>CHOOSE YOUR DESTINY</small><h3>选择你想唤醒的英雄</h3><p>抽奖券独立于金币。基础概率10%为平衡初值，第20抽内必得；每位英雄独立保底，切换不清零。抽到目标后停止，未花的十连券保留。</p><div class="summon-targets">${targets.map(id=>`<label><input type="radio" name="solo-summon-target" value="${id}" ${id===targets[0]?'checked':''}><span class="solo-hero-art" style="${splashStyle(id)}"></span><b>${SOLO_NAMES[id]}</b><small>已抽 ${p.pity[id]||0} / 20</small></label>`).join('')}</div><button data-summon="1" ${!targets.length?'disabled':''}>召唤一次 · 1券</button><button data-summon="10" ${!targets.length?'disabled':''}>召唤十次 · 最多10券</button></div>`;}
 action(event){const b=event.target.closest('button');if(!b)return;const p=this.getProfile(),w=this.getWorld(),h=this.hero;if(b.hasAttribute('data-close'))return this.close();if(b.dataset.panel){this.panel=b.dataset.panel;this.message='';return this.render();}if(b.dataset.item){this.selectedItem=b.dataset.item;this.panel='bag';return this.render();}this.mutate(()=>{if(b.hasAttribute('data-select-hero')){p.selected=h;return '已设为出战英雄';}if(b.dataset.learn)learnSkill(p,h,b.dataset.learn);if(b.dataset.equipSkill){equipSkill(p,h,b.dataset.equipSkill);if(w?.hero===h)w.player.recast=null;}if(b.dataset.upgradeSkill)upgradeSkill(p,h,b.dataset.upgradeSkill);if(b.dataset.equip)equipItem(p,h,b.dataset.equip);if(b.dataset.unequip)p.heroes[h].equipment[b.dataset.unequip]=null;if(b.dataset.use)useItem(p,b.dataset.use,h,w?.hero===h?w.player:null);if(b.dataset.sell)sellItem(p,b.dataset.sell);if(b.dataset.choice){chooseHero(p,b.dataset.choice,this.dialog.querySelector('#choice-hero')?.value);return '新的英雄已加入你的队伍';}if(b.hasAttribute('data-transfer')){if(w)throw Error('请在关卡外传输功力');transferPower(p,h,this.dialog.querySelector('#transfer-target')?.value);return '经验传输完成，传出英雄已回到1级';}if(b.dataset.combine)combineStones(p,b.dataset.combine);if(b.dataset.forge)forgeItem(p,b.dataset.forge);if(b.dataset.levelEquipment)levelEquipment(p,b.dataset.levelEquipment);if(b.dataset.summon){const target=this.dialog.querySelector('[name="solo-summon-target"]:checked')?.value,results=summonSolo(p,target,Number(b.dataset.summon));return results.some(r=>r.hero)?'星辉回应 · 已获得'+SOLO_NAMES[target]:`获得${results.length}件补给，保底进度已保存`;}});}
}





